const img = await readImage('uploads/九经书院书法图.jpg');
const W = img.width, H = img.height;
// draw native
const src = createCanvas(W, H);
const sctx = src.getContext('2d');
sctx.drawImage(img, 0, 0);
const data = sctx.getImageData(0, 0, W, H);
const p = data.data;

// ink target color (site ink)
const inkR = 0x22, inkG = 0x20, inkB = 0x1d;
// luminance keying: dark -> opaque ink, light paper -> transparent
let minX = W, minY = H, maxX = 0, maxY = 0;
const aBuf = new Float32Array(W * H);
for (let i = 0; i < W * H; i++) {
  const r = p[i*4], g = p[i*4+1], b = p[i*4+2];
  const lum = 0.299*r + 0.587*g + 0.114*b;
  // alpha ramp: lum<=110 => 1 ; lum>=195 => 0
  let a = (195 - lum) / (195 - 110);
  a = Math.max(0, Math.min(1, a));
  aBuf[i] = a;
  if (a > 0.35) {
    const x = i % W, y = (i / W) | 0;
    if (x < minX) minX = x; if (x > maxX) maxX = x;
    if (y < minY) minY = y; if (y > maxY) maxY = y;
  }
}
// write ink color + alpha back
for (let i = 0; i < W * H; i++) {
  p[i*4] = inkR; p[i*4+1] = inkG; p[i*4+2] = inkB;
  p[i*4+3] = Math.round(aBuf[i] * 255);
}
sctx.putImageData(data, 0, 0);

// tight crop with small padding
const pad = 8;
minX = Math.max(0, minX - pad); minY = Math.max(0, minY - pad);
maxX = Math.min(W-1, maxX + pad); maxY = Math.min(H-1, maxY + pad);
const cw = maxX - minX + 1, ch = maxY - minY + 1;
log('bbox', minX, minY, cw, ch);

// upscale 3x, smoothed
const scale = 3;
const out = createCanvas(cw * scale, ch * scale);
const octx = out.getContext('2d');
octx.imageSmoothingEnabled = true;
octx.imageSmoothingQuality = 'high';
octx.drawImage(src, minX, minY, cw, ch, 0, 0, cw*scale, ch*scale);
await saveFile('assets/calligraphy-mark.png', out);
