  const d=x.getImageData(0,0,W,H);const p=d.data;
  let minX=W,minY=H,maxX=0,maxY=0;
  for(let i=0;i<W*H;i++){const r=p[i*4],g=p[i*4+1],b=p[i*4+2];const lum=0.299*r+0.587*g+0.114*b;
   let a=(lum-90)/(200-90);a=Math.max(0,Math.min(1,a));a=Math.pow(a,1.3);
   p[i*4]=0xef;p[i*4+1]=0xe9;p[i*4+2]=0xdc;p[i*4+3]=Math.round(a*255);
